'use strict';
// Wraps build/kunsolve.js (Emscripten output, WASM embedded) plus a small worker message handler into ONE string assigned to
// window.KUNSOLVE_WORKER_SOURCE, in kunsolve-bundle.js. A page loads that file with an ordinary <script> tag (works from file://
// and http://) and solver-client.js starts the worker from a Blob, because browsers refuse Worker('file:///...') and fetch() on file://.
const fs=require('fs'),path=require('path');
const GLUE=`
;(function(){self.onmessage=async function(e){var m=e.data;if(!m||m.type!=='solve')return;try{var M=await createKunsolve({onProgress:function(l){self.postMessage({type:'progress',id:m.id,line:l});},print:function(){},printErr:function(){}});var json=M.ccall('kun_solve','string',['string','string'],[m.code,m.flags||'']);self.postMessage({type:'result',id:m.id,result:JSON.parse(json),heapMB:M.HEAPU8.length>>20});}catch(err){self.postMessage({type:'error',id:m.id,message:String(err&&err.message||err)});}};})();`;
function run(){
 const src=fs.readFileSync(path.join(__dirname,'build','kunsolve.js'),'utf8');
 // base64 of "\0asm" (the WASM magic): proves the binary is embedded as base64 (-sSINGLE_FILE_BINARY_ENCODE=0) and intact.
 // A raw binary-string embedding breaks when the file passes through anything that treats it as text (NUL bytes get lost).
 if(!src.includes('AGFzbQ'))throw new Error('build/kunsolve.js has no base64 WASM payload: rebuild with `node wasm/build.js` (it passes -sSINGLE_FILE_BINARY_ENCODE=0)');
 const out=path.join(__dirname,'kunsolve-bundle.js');
 fs.writeFileSync(out,'// Generated by Solver/wasm/bundle.js from build/kunsolve.js (see build.js). Do not edit.\nwindow.KUNSOLVE_WORKER_SOURCE='+JSON.stringify(src+GLUE).replace(/[\u0080-\uffff]/g,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0'))+';\n');
 console.log('OK: '+out+' ('+(fs.statSync(out).size>>10)+' KB)');
}
if(require.main===module)run();
module.exports={run};
